"}\n\n// === RENDER ==============================================================\nfunction render() {\n  // Clear canvas\n  ctx.fillStyle = \"#0f1320\";\n  ctx.fillRect(0, 0, canvas.width, canvas.height);\n\n  // Draw hazards\n  ctx.fillStyle = \"#ff00aa\";\n  for (const h of hazards) {\n    ctx.beginPath();\n    ctx.arc(h.x, h.y, h.radius, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  // Draw player\n  ctx.fillStyle = \"#7df9ff\";\n  ctx.beginPath();\n  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);\n  ctx.fill();\n\n  // HUD: score\n  ctx.fillStyle = \"#e6e6f0\";\n  ctx.font = \"16px ui-sans-serif, system-ui\";\n  ctx.textAlign = \"left\";\n  ctx.fillText(`Score ${score}`, 12, 22);\n\n  // Game over overlay\n  if (state === \"gameover\") {\n    ctx.fillStyle = \"rgba(10,10,15,0.7)\";\n    ctx.fillRect(0, 0, canvas.width, canvas.height);\n    ctx.textAlign = \"center\";\n    ctx.font = \"44px ui-sans-serif, system-ui\";\n    ctx.fillStyle = \"#ff52ae\";\n    ctx.fillText(\"Game Over\", canvas.width / 2, canvas.height / 2 - 20);\n    ctx.font = \"20px ui-sans-serif, system-ui\";\n    ctx.fillStyle = \"#e6e6f0\";\n    ctx.fillText(`Final score ${score}`, canvas.width / 2, canvas.height / 2 + 14);\n    ctx.font = \"16px ui-sans-serif, system-ui\";\n    ctx.fillStyle = \"#a5a5b8\";\n    ctx.fillText(\"Press R or click Restart\", canvas.width / 2, canvas.height / 2 + 42);\n  }\n}\n\n// === LOOP/UPDATE ==========================================================\nlet lastTime = performance.now();\nlet loopId = null;\nfunction startLoop() {\n  if (loopId !== null) cancelAnimationFrame(loopId);\n  function tick(now) {\n    try {\n      const dt = Math.min((now - lastTime) / 1000, 0.1);\n      lastTime = now;\n      // Player movement\n      if (state === \"playing\") {\n        const speed = 300; // PLAYER_SPEED\n        let dirX = 0, dirY = 0;\n        if (keys.has('ArrowRight') || keys.has('d') || keys.has('D')) dirX += 1;\n        if (keys.has('ArrowLeft') || keys.has('a') || keys.has('A')) dirX -= 1;\n        if (keys.has('ArrowUp') || keys.has('w') || keys.has('W')) dirY -= 1;\n        if (keys.has('ArrowDown') || keys.has('s') || keys.has('S')) dirY += 1;\n        // Normalize diagonal movement\n        if (dirX !== 0 && dirY !== 0) {\n          const norm = Math.sqrt(2);\n          dirX /= norm; dirY /= norm;\n        }\n        player.x = Math.min(Math.max(player.x + dirX * speed * dt, 0), canvas.width);\n        player.y = Math.min(Math.max(player.y + dirY * speed * dt, 0), canvas.height);\n      }\n      update(dt);\n      render();\n      publishState();\n    } catch (e) {\n      console.error('loop error', e);\n    }\n    loopId = requestAnimationFrame(tick);\n  }\n  loopId = requestAnimationFrame(tick);\n}\n\n// === RESET ==============================================================\nfunction reset() {\n  // Reset game state\n  player.x = canvas.width / 2;\n  player.y = canvas.height / 2;\n  player.radius = player.radiusSmall;\n  player.vx = 0;\n  player.vy = 0;\n  hazards = [];\n  score = 0;\n  state = \"playing\";\n  spawnTimer = 0;\n  // Cancel previous loop and start anew\n  startLoop();\n  // Publish initial state\n  publishState();\n}\n\n// === BOOT ==============================================================\nreset();\n\n  </script>"

